/* Transparent, deterministic AI interactions for client demonstrations. */
const intelligenceProfiles=[
['Proposal copilot',['Find gaps in this RFP response','Draft an executive summary','Model proposal preparation time'],'Sample RFP · 12 requirements · 90-day pilot','Focus the review on measurable acceptance criteria, a named delivery owner, and the assumptions behind the timeline. A draft should not promise outcomes the team has not validated.','Executive summary\nWe propose a focused operations pilot to connect the team’s source information with an AI-assisted workflow. The first phase confirms requirements and baseline performance. The team then reviews a working application against agreed acceptance criteria. Delivery scope, responsibilities, and success measures will be confirmed before implementation.',1,'proposals',8,180],
['Campaign copilot',['Identify useful webinar follow-up angles','Draft an email and three follow-ups','Model follow-up preparation time'],'Sample webinar transcript · attendee context','Lead with the attendee’s relevant topic, offer one useful resource, and use a single clear next step. Follow-ups should add new value instead of repeating the first email.','Subject: Following up on the workflow discussion\nThanks for joining our webinar. Your interest in reducing manual handoffs stood out. Would a short example of a connected workflow be useful?\n\nFollow-up 1 · Day 3: Share a relevant example and ask which step takes the most time.\nFollow-up 2 · Day 7: Offer a checklist for identifying the first practical AI use case.\nFollow-up 3 · Day 14: Ask whether a brief workflow review would be timely.',1,'attendee follow-ups',120,12],
['Qualification copilot',['Explain lead prioritization','Draft a sales handoff','Model lead-review time'],'Sample engagement signals · account context','Combine account fit with recent intent and keep the reasons visible. A high score is a review priority, not a guarantee of a qualified opportunity. Confirm missing decision-maker and timing information.','Sales handoff\nAccount: Northstar Manufacturing\nRelevant signals: webinar engagement, an operations inquiry, and a referral.\nHypothesis: the team may need a clearer way to coordinate operational work.\nNext step: confirm the specific workflow, current tools, decision owner, and urgency before proposing a solution.',1,'leads reviewed',160,8],
['Persona research copilot',['Compare likely persona objections','Draft a refined concept','Model concept-review time'],'Simulated personas · concept brief','Finance may challenge the payback assumptions; delivery may question ownership; IT may ask about access and integrations. Treat these as simulated perspectives to investigate, not findings from real customer research.','Refined concept\nStart with one defined workflow and a named owner. Use approved source data, preserve human review at consequential steps, and evaluate the application against a baseline agreed with the team. Expand only after the first workflow demonstrates useful results.',1,'concept reviews',12,90],
['Budget copilot',['Review budget assumptions','Draft a department justification','Model budget preparation time'],'Current sample department plans','Check recurring versus one-time costs, headcount assumptions, and whether the plan includes adoption and ongoing support. Ask each department to tie requests to a measurable operating need.','Department budget justification\nThe request supports a defined workflow improvement. Separate implementation costs from recurring platform and model usage. Review the estimate against prior spending, expected adoption, and the owner responsible for measuring the outcome. Approve changes through the department’s normal review process.',1,'budget requests',24,60],
['Revenue copilot',['Explain pipeline exposure','Draft the leadership sales brief','Model sales-report preparation time'],'Sample sales pipeline · performance views','Inspect concentration in late-stage opportunities and compare the expected close dates with evidence from the account. Stage percentages alone do not establish a reliable forecast.','Leadership sales brief\nReview current performance alongside the opportunity pipeline. Focus discussion on the largest late-stage deals, what must happen before close, and changes since the previous review. Separate confirmed results from weighted pipeline and scenario assumptions.',1,'sales reports',20,120],
['Capacity copilot',['Find workload pressure','Draft a staffing recommendation','Model resource-planning time'],'Current sample team assignments','Inspect overloaded team members before moving work. Reassignment should consider skills, dates, project context, and the cost of switching—not just available hours.','Staffing recommendation\nReview the highest-load assignments with the delivery owner. Confirm which tasks can move, which skills are required, and the available capacity of the proposed recipient. Preserve critical delivery dates and ask both owners to review the revised plan before committing.',1,'planning cycles',16,75],
['Project workspace copilot',['Summarize project coordination needs','Draft a client project update','Model coordination time'],'Sample project plan · files and discussion context','Keep each decision attached to its project context. Make ownership and the next milestone visible to clients and contractors, with access appropriate to their role.','Client project update\nThe team is reviewing the current milestone and open tasks. The next checkpoint should confirm the deliverable owner, acceptance criteria, and any decision needed from the client. Supporting files and discussions should remain linked to the project so everyone can follow the same context.',1,'project updates',80,20],
['Insights copilot',['Identify cross-report questions','Draft an executive insight summary','Model report analysis time'],'Sample reporting workspace · source context','Compare the reporting periods and metric definitions before combining conclusions. Separate observed results from inferred causes and keep the original source available for review.','Executive insight summary\nReview revenue performance, delivery capacity, and spending together. Confirm whether the reporting periods align, then identify the changes that require a decision. Where reports disagree, note the discrepancy and assign a source owner before drawing a conclusion.',2,'reports analyzed',30,60],
['Forecast copilot',['Explain the forecast drivers','Draft a scenario narrative','Model forecast preparation time'],'Current sample forecast assumptions','Show the baseline before discussing an alternative. Explain which inputs changed, which stayed fixed, and how the result depends on those assumptions. A scenario is not a prediction.','Scenario narrative\nThe alternative forecast reflects changes to pipeline growth and win rate relative to the baseline. Review both drivers with the commercial team and compare the result with current opportunity evidence. Document the conditions that would make the scenario plausible.',2,'forecast cycles',8,180],
['Investment copilot',['Challenge the ROI assumptions','Draft a business-case recommendation','Model business-case preparation time'],'Current investment inputs · benefit and cost model','Evaluate adoption, the loaded value of time, recurring costs, and the delay before benefits begin. Time released is capacity; it is not automatically a cash saving.','Investment recommendation\nProceed only after validating the baseline workload and the expected adoption rate. Compare the full implementation and running cost with realistic benefits. Use sensitivity analysis to show which assumptions have the largest effect on payback, then define a review checkpoint.',2,'business cases',12,120],
['Delivery copilot',['Identify portfolio review priorities','Draft a portfolio status note','Model portfolio reporting time'],'Sample initiative register · milestones and decisions','Look for decisions that block multiple tasks, milestones without a clear owner, and projects whose status lacks evidence. Prioritize the next decision rather than repeating the status label.','Portfolio review note\nReview each initiative against its next milestone. Record the owner, due date, and decision required to proceed. Escalate issues with a specific ask and enough context for leadership to decide. Confirm progress against the deliverable, not activity alone.',2,'portfolio updates',24,90],
['Prospecting copilot',['Evaluate a prospecting angle','Draft three outreach directions','Model prospect research time'],'Sample research brief · account queue','Anchor the outreach in a plausible workflow problem and distinguish researched facts from hypotheses. Avoid unsupported claims about the account. Review the message and recipient before sending.','Direction 1 · Operational clarity\nCould a shared view of tasks and handoffs help your team reduce manual coordination?\n\nDirection 2 · Better decisions\nWe build applications that connect reports and make the assumptions behind decisions easier to inspect.\n\nDirection 3 · Practical first step\nWould it be useful to map one repetitive workflow and explore what a focused AI application could look like?\n\nUse each direction as a starting point for an email or LinkedIn post, with account-specific evidence added before use.',1,'accounts researched',100,18],
['Relationship copilot',['Explain the relationship risks','Draft a client recovery plan','Model account-review time'],'Sample health scores · renewal dates · account evidence','Start with the evidence behind a declining score. Sponsor changes, unresolved issues, and renewal timing require different actions. Assign an accountable owner and confirm the client’s perspective.','Client recovery plan\n1. Confirm the sponsor and decision owner.\n2. Review unresolved concerns using the account evidence.\n3. Agree on a near-term resolution and a measurable checkpoint.\n4. Record the next client conversation and its owner.\n5. Review the signals again after the action; do not assume that completing the task improves health.',3,'account reviews',30,45]
];
let intelligenceApp=0,intelligenceMode='analysis';
const intelligenceChats={};
function intelligenceStrip(i){const p=intelligenceProfiles[i];return `<section class="intelligence-strip"><div class="intelligence-strip-label">${icon('spark')}<div><b>${p[0]}</b><small>Try an AI-assisted workflow · Simulation</small></div></div><div class="intelligence-shortcuts">${p[1].map((q,j)=>`<button onclick="intelligenceOpen(${i},${j})">${j===0?'Analyze the context':j===1?'Generate a draft':'Explore a what-if'} ${icon('arrow')}</button>`).join('')}</div></section>`}
const clientIntroWithStory=studioProductIntro;
studioProductIntro=function(){return clientIntroWithStory()+intelligenceStrip(current)};
function intelligenceOpen(i,j=0){intelligenceApp=i;intelligenceMode=['analysis','draft','scenario'][j];if(!intelligenceChats[i])intelligenceChats[i]=[];intelligenceDraw()}
function intelligenceContext(i){if(i===4)return 'The current combined department plan is '+money(state.budget.reduce((s,v)=>s+Number(v),0))+'.';if(i===6)return 'The sample team currently has '+state.team.reduce((s,t)=>s+t[2],0)+' assigned hours against 200 weekly hours of capacity.';if(i===9)return 'Current model inputs: '+state.growth+'% pipeline growth and '+state.win+'% win rate.';if(i===13)return healthAccounts.filter(a=>healthScore(a)<80).map(a=>a.name+': '+healthScore(a)+'/100, renewal in '+a.days+' days').join('. ')+'.';if(i===11)return 'Review '+(projects.length+(state.newProjects||[]).length)+' sample initiatives and their outstanding decisions.';return intelligenceProfiles[i][2]+'.'}
function intelligenceDraw(){const i=intelligenceApp,p=intelligenceProfiles[i],chat=intelligenceChats[i]||[];draw(p[0],`<div class="intelligence-banner"><span>INTERACTIVE AI SIMULATION</span><p>Explore sample analysis and outputs. This demo uses predefined responses and calculations, not a live AI model.</p></div><div class="intelligence-tabs">${['analysis','draft','scenario'].map((m,j)=>`<button class="${intelligenceMode===m?'active':''}" onclick="intelligenceMode='${m}';intelligenceDraw()">${['Analyze','Draft & refine','What-if model'][j]}</button>`).join('')}</div>${intelligenceMode==='analysis'?`<div class="intelligence-source"><span>WORKSPACE CONTEXT</span><p>${esc(intelligenceContext(i))}</p></div><div class="intelligence-answer"><h3>${p[1][0]}</h3><p>${p[3]}</p><div class="intelligence-recommendation"><span>Recommended next step</span><p>${clientValue[i][2]}</p></div></div><div class="intelligence-chat" aria-live="polite">${chat.map(m=>`<div class="intelligence-question">${esc(m.q)}</div><div class="intelligence-chat-answer">${esc(m.a)}</div>`).join('')}</div><div class="intelligence-prompts">${['What should we validate?','What needs human review?','How would this fit our business?'].map(q=>`<button onclick="intelligenceAsk(${JSON.stringify(q).replaceAll('"','&quot;')})">${q}</button>`).join('')}</div><div class="intelligence-compose"><textarea id="intelligenceQuestion" aria-label="Ask the simulated copilot" placeholder="Ask about the workflow, risks, or next steps…" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();intelligenceAsk()}"></textarea>${ib('Ask','intelligenceAsk()','arrow','primary')}</div>`:''}${intelligenceMode==='draft'?`<div class="intelligence-source"><span>EDITABLE SAMPLE OUTPUT</span><p>${p[1][1]}. Adjust the language for your audience before using it.</p></div><div class="intelligence-draft-tools">${['Concise','Executive','Action checklist'].map(t=>`<button onclick="intelligenceRefine('${t}')">${t}</button>`).join('')}</div><textarea class="intelligence-draft" id="intelligenceDraft" aria-label="Editable AI draft">${esc(localStorage.getItem("nine67-ai-draft-"+i)||p[4])}</textarea><div class="health-buttons">${ib('Save draft','intelligenceSaveDraft()','check','primary')}${ib('Download draft','intelligenceDownloadDraft()','download')}</div><p id="intelligenceSaved" class="exp-note" aria-live="polite">Drafts are saved only in this browser.</p>`:''}${intelligenceMode==='scenario'?intelligenceScenario(i):''}<div class="intelligence-bottom-actions">${ib('Open related workspace',`closeDrawer();tab=${p[5]};render();document.querySelector('.experience').scrollIntoView({behavior:'smooth'})`,'arrow')}</div>`)}
function intelligenceAsk(q){const i=intelligenceApp,p=intelligenceProfiles[i],text=(q||$('#intelligenceQuestion').value).trim();if(!text)return;let answer;if(/human|review|approv|risk|safe/i.test(text))answer='Keep people responsible for approval. '+p[3]+' In this workflow, review the evidence and edit the output before any external or consequential action.';else if(/valid|source|data|evidence|why/i.test(text))answer='Start with the sample context: '+intelligenceContext(i)+' Confirm the source, reporting period, completeness, and who owns it. Replace these sample inputs with approved client information in a real implementation.';else if(/our|business|fit|custom|integrat/i.test(text))answer='For your team, begin with: '+clientValue[i][1]+' We would tailor '+clientValue[i][4].join(', ').toLowerCase()+' to your process, source systems, and review rules. The implementation would be scoped around your actual workflow.';else if(/draft|write|email|summar|plan/i.test(text))answer='The Draft & refine tab contains an editable example for this application. You can make it concise, turn it into an action checklist, save it, or download it for review.';else if(/time|cost|saving|what.if|simulat/i.test(text))answer='Open the What-if model to change monthly volume, current minutes per task, and the assumed reduction. The result shows gross time released before validation effort; it is an illustration, not a promised saving.';else answer='This demo can explore the workflow, evidence to validate, human review, sample drafts, and time scenarios. For “'+text+'”, the relevant starting point is: '+p[3]+' Try a question about data, risk, a draft, or time savings.';intelligenceChats[i].push({q:text,a:answer});intelligenceDraw()}
function intelligenceRefine(t){const p=intelligenceProfiles[intelligenceApp];const value=t==='Concise'?clientValue[intelligenceApp][2]+'\n\nNext step: '+p[3].split('. ')[0]+'.':t==='Executive'?'Executive recommendation\n\n'+clientValue[intelligenceApp][2]+'\n\nDecision required\nConfirm the workflow owner, source information, approval process, and a measurable baseline before implementation.\n\nContext\n'+intelligenceContext(intelligenceApp):'Review checklist\n\n'+clientValue[intelligenceApp][4].map((x,j)=>(j+1)+'. Confirm '+x.toLowerCase()+'.').join('\n')+'\n4. Validate the source and assumptions.\n5. Assign an owner and review the output.\n6. Agree on a measurable success checkpoint.';$('#intelligenceDraft').value=value}
function intelligenceSaveDraft(){localStorage.setItem('nine67-ai-draft-'+intelligenceApp,$('#intelligenceDraft').value);$('#intelligenceSaved').textContent='Draft saved in this browser. Use Download to share a copy.'}
function intelligenceDownloadDraft(){download('Nine-67-'+toolsList[intelligenceApp][0].toLowerCase().replaceAll(' ','-')+'-sample-draft.txt',$('#intelligenceDraft').value)}
function intelligenceScenario(i){const p=intelligenceProfiles[i];return `<div class="intelligence-source"><span>ADJUSTABLE TIME SCENARIO</span><p>Explore the potential effect on ${p[6]}. Change the assumptions to match a hypothetical team.</p></div><div class="intelligence-scenario-controls"><label>Monthly ${p[6]}<input id="aiVolume" type="number" min="1" max="10000" value="${p[7]}" oninput="intelligenceCalculate()"></label><label>Current minutes per task<input id="aiMinutes" type="number" min="1" max="1440" value="${p[8]}" oninput="intelligenceCalculate()"></label><label class="intelligence-range">Assumed time reduction <output id="aiReductionLabel">35%</output><input id="aiReduction" type="range" min="0" max="80" value="35" oninput="intelligenceCalculate()"></label></div><div class="intelligence-scenario-results"><div><span>Current monthly effort</span><b id="aiBaseline">${(p[7]*p[8]/60).toFixed(1)}<small> hrs</small></b><i class="intelligence-baseline-bar"></i></div><div><span>Illustrative effort with AI</span><b id="aiFuture">${(p[7]*p[8]/60*.65).toFixed(1)}<small> hrs</small></b><i id="aiFutureBar" style="width:65%"></i></div></div><div class="intelligence-scenario-benefit"><span>Gross time released</span><strong id="aiReleased">${(p[7]*p[8]/60*.35).toFixed(1)} hours / month</strong></div><p class="exp-note">Volume × minutes ÷ 60 = baseline hours. Scenario hours = baseline × (1 − reduction). Excludes setup, adoption, and extra review effort. Released capacity is not automatically cash savings.</p>`}
function intelligenceCalculate(){const v=Math.max(0,Math.min(10000,Number($('#aiVolume').value)||0)),m=Math.max(0,Math.min(1440,Number($('#aiMinutes').value)||0)),r=Number($('#aiReduction').value),base=v*m/60;$('#aiReductionLabel').textContent=r+'%';$('#aiBaseline').textContent=base.toFixed(1)+' hrs';$('#aiFuture').textContent=(base*(1-r/100)).toFixed(1)+' hrs';$('#aiReleased').textContent=(base*r/100).toFixed(1)+' hours / month';$('#aiFutureBar').style.width=(100-r)+'%'}
render();
